-- TOC entry 1008 (class 1255 OID 83108)
-- Name: generate_ways_linestrings(); Type: PROCEDURE; Schema: stlustehl; Owner: stlustehl
--

CREATE PROCEDURE stlustehl.generate_ways_linestrings()
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- alte Daten löschen
  DELETE FROM ways_linestrings;

  -- neue Linien einfügen
  SELECT
    w.id,
    ST_MakeLine(n.geom ORDER BY wn.sequence_id) AS geom
  FROM
    ways w
  JOIN way_nodes wn ON w.id = wn.way_id
  JOIN nodes n ON wn.node_id = n.id
  GROUP BY w.id;

  RAISE NOTICE 'Ways erfolgreich in Linestrings umgewandelt.';
END;
$$;


ALTER PROCEDURE stlustehl.generate_ways_linestrings() OWNER TO stlustehl;

